G=load()

def solve(I):
    H,W=len(I),len(I[0])
    # find block color (2) bbox and marker color
    cols2=[(r,c) for r in range(H) for c,x in enumerate(I[r]) if x==2]
    rs=[r for r,_ in cols2]; cs=[c for _,c in cols2]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    mk=[x for x in {v for row in I for v in row} if x not in (0,2)]
    mk=mk[0]
    markers=[(r,c) for r in range(H) for c,x in enumerate(I[r]) if x==mk]
    sil=set(range(c0,c1+1))
    O=[row[:] for row in I]
    def strip(row,side):
        lo,hi = (0,c0-1) if side=='L' else (c1+1,W-1)
        for c in range(lo,hi+1): O[row][c]=2
    def silhouette_row(r,start,end):
        for c in range(start,end+1): O[r][c]=2
    # top band: rows above block, silhouette minus columns of above markers
    above=[c for (r,c) in markers if r<r0]
    below=[c for (r,c) in markers if r>r1]
    for r in range(0,r0):
        for c in sil:
            if c not in above: O[r][c]=2
    # bottom band: rows below, silhouette minus below marker columns
    for r in range(r1+1,H):
        for c in sil:
            if c not in below: O[r][c]=2
    # markers in block rows: own-row far-side strip if col%5 in {1,2,4}; consecutive pairs -> between strips
    Lmarks=[(r,c) for (r,c) in markers if c<c0 and r0<=r<=r1]
    Rmarks=[(r,c) for (r,c) in markers if c>c1 and r0<=r<=r1]
    for (r,c) in Lmarks:
        if c%5 in (1,2,4): strip(r,'R')
    for (r,c) in Rmarks:
        if c%5 in (1,2,4): strip(r,'L')
    for side,S in (('L',Lmarks),('R',Rmarks)):
        S.sort()
        for a,b in zip(S,S[1:]):
            for rr in range(a[0]+1,b[0]): strip(rr,side)
    return O

